import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(16).t5Shrzgd.png",l="/assets/image%20(17).BvRZQ6bi.png",r="/assets/image%20(18).C3l9la_v.png",s="/assets/image%20(19).DB9OCWoK.png",c="/assets/image%20(20).C4HQYJft.png",d="/assets/image%20(21).zRD6mXYk.png",k=JSON.parse('{"title":"Amazon Elastic Beanstalk","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/amazon-elastic-beanstalk.md","filePath":"getting-started/amazon-elastic-beanstalk.md"}'),p={name:"getting-started/amazon-elastic-beanstalk.md"};function u(g,e,h,m,f,b){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="amazon-elastic-beanstalk" tabindex="-1">Amazon Elastic Beanstalk <a class="header-anchor" href="#amazon-elastic-beanstalk" aria-label="Permalink to &quot;Amazon Elastic Beanstalk&quot;">​</a></h1><h2 id="hosting-tradeboard-in-the-cloud-using-amazon-aws-elastic-beanstalk" tabindex="-1">Hosting Tradeboard in the Cloud using Amazon AWS Elastic Beanstalk <a class="header-anchor" href="#hosting-tradeboard-in-the-cloud-using-amazon-aws-elastic-beanstalk" aria-label="Permalink to &quot;Hosting Tradeboard in the Cloud using Amazon AWS Elastic Beanstalk&quot;">​</a></h2><p><br><a href="https://rajeevupadhyay.com/" target="_blank" rel="noreferrer">Tradeboard</a> is an open-source algo trading platform, offering a wide range of features for both beginners and experienced traders. This tutorial guides you through the process of hosting Tradeboard in the cloud using Amazon AWS Elastic Beanstalk.</p><p><strong>Prerequisites:</strong></p><ul><li>An Amazon AWS account</li><li>VS Code (or any code editor with Git installed)</li><li>A hosting account with DNS management and custom domain(Cloudflare is recommended)</li></ul><p><strong>Steps by Step Instruction to host Tradeboard in Amazon Cloud with custom domain</strong></p><p><strong>Clone the Tradeboard Repository:</strong></p><ul><li>Go to the <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">Tradeboard GitHub repository</a>.</li><li>Copy the repository link.</li><li>Open your VS Code and navigate to your project folder.</li><li>Open a new terminal in VS Code and type <strong>git clone</strong> <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">**https://github.com/wesoftcorp/tradeboard-docs</a> and press enter.</li><li>This will download the Tradeboard application locally in your VS Code.</li></ul><p><strong>Configure the .env File</strong></p><ul><li><p>Copy the <code>.sample.env</code> file in the Tradeboard project to <code>.env</code> (<code>cp .sample.env .env</code>).</p></li><li><p>Update the REDIRECT_URL to your custom domain.</p></li><li><p>For example, if your custom domain for angel trading account is opendash.app, update it to <a href="https://opendash.app/angel/callback" target="_blank" rel="noreferrer">https://opendash.app/angel/callback</a>.</p></li><li><p>If you’re not using HTTPS, use <a href="http://tradeboard.app/angel/callback" target="_blank" rel="noreferrer">http://tradeboard.app/angel/callback</a>.</p></li><li><p>Make sure to update the HOST_SERVER to your custom domain as well as shown in the video.</p></li><li><p>You might also want to update the BROKER_API_KEY and BROKER_API_SECRET according to your broker credentials.</p></li><li><p>Generate APP_KEY, API_KEY_PEPPER and FERNET_SALT <strong>before</strong> you zip the bundle, and put the generated values in <code>.env</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import secrets; print(secrets.token_hex(32))&quot;</span></span></code></pre></div><p>Run it three times and paste one value into each key, replacing the <code>TRADEBOARD_PLACEHOLDER_...</code> text. On a normal install Tradeboard generates these itself on first start, but an Elastic Beanstalk deploy replaces the whole application bundle each time, so a value generated on the instance would be lost on the next deploy. Rotating <code>API_KEY_PEPPER</code> or <code>FERNET_SALT</code> invalidates every stored password hash and every encrypted broker token, so they must be fixed in the bundle and kept identical across deploys.</p></li><li><p>Save the changes.</p></li></ul><p><strong>Create the Elastic Beanstalk Application</strong></p><ul><li>Go to the <a href="https://aws.amazon.com/" target="_blank" rel="noreferrer">AWS Management Console</a> and sign in.</li><li>Select the desired region (e.g., Asia Pacific (Mumbai) ap-south-1).</li><li>Search for “Elastic Beanstalk”.</li><li>Click on “Create application”.</li><li>Provide an application name (e.g., tradeboard) and an environment name (e.g., tradeboard-env).</li><li>Ensure the domain name is available (e.g., tradeboard.ap-south-1.elasticbeanstalk.com).</li><li>Provide a description for your environment (optional).</li><li>Select a Python platform branch that provides Python 3.12 or newer.</li><li>Select “4.1.0 (Recommended)” as the platform version.</li><li>For “Application code”, choose “Upload your code”.</li><li>Give a version label (e.g., 1.0.0.1).</li><li>Choose “Local file” for “Source code origin”.</li><li>Select the zipped Tradeboard project file you created earlier.</li><li>Choose “Single instance (free tier eligible)” as the configuration preset (or choose “Custom configuration” for more options).</li><li>Click on “Next” to proceed.</li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p><strong>Configure Service Access:</strong></p><ul><li>Select the existing service role you created earlier.</li><li>If you don’t have one, click on “Create and use new service role”.</li><li>Select your EC2 key pair (e.g., test).</li><li>If you don’t have an EC2 key pair, click on “Choose an EC2 key pair” and create a new one.</li><li>Select the existing EC2 instance profile (e.g., “aws-elasticbeanstalk-ec2-role-flaskenv”).</li><li>If you don’t have one, click on “View permission details” and create a new instance profile.</li><li>Click on “Next”.</li></ul><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><p><strong>Configure VPC Settings</strong></p><ul><li>Select the default VPC. You can create a new VPC, if needed.</li><li>This is the virtual network where your Elastic Beanstalk environment will be deployed.</li></ul><p><strong>Activate Public IP Address and Instance Subnet:</strong></p><ul><li>Ensure the Public IP address is enabled for your instance. This allows your application to be accessible from the internet.</li><li>Choose an instance subnet from your VPC.</li></ul><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><p><strong>Configure Security Group:</strong></p><ul><li>By default, select the default security group.</li><li>This will allow your application to connect to the internet.</li><li>If you want to restrict access, you can create a new security group and add rules to control incoming and outgoing traffic.</li><li>Click on “Next”.</li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p><strong>Configure Instance Type, Load Balancer, and CloudWatch Logs:</strong></p><ul><li>Choose an instance type (e.g., T3 micro, T3 Small).</li><li>If you are looking for a free tier option, use T3 micro.</li><li>Select “Single instance” if you don’t need a load balancer.</li><li>Choose “Enhanced” for health reporting (optional).</li><li>Choose the default settings for CloudWatch logs (optional).</li><li>Click on “Next”.</li></ul><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><p><strong>Review and Submit:</strong></p><ul><li>Review all the configuration steps.</li><li>Make sure all the settings are correct.</li><li>Click on “Submit”.</li><li>This will initiate the automated provisioning of the servers in the backend.</li></ul><figure><img src="'+d+'" alt=""><figcaption></figcaption></figure><p>After deploying your Tradeboard application on Elastic Beanstalk, you need to configure your custom domain to point to the Elastic Beanstalk environment. This involves creating a CNAME record in your DNS settings. Here’s how to do it:</p><p><strong>Access Your DNS Provider:</strong></p><ul><li>Log in to your DNS provider (e.g., Cloudflare, GoDaddy, Namecheap, etc.)</li><li>Find your domain’s DNS management section.</li></ul><p><strong>Create a CNAME Record:</strong></p><ul><li>Click on “Add record” or similar to create a new record.</li><li><strong>Name:</strong> Enter the subdomain you want to use (e.g., trade). This will be the part of your custom domain that will point to your Elastic Beanstalk application (e.g., trade.tradeboard.app).</li><li><strong>Type:</strong> Select “CNAME”.</li><li><strong>Value:</strong> Copy the Elastic Beanstalk domain generated by AWS. It will look something like this: tradeboard.ap-south-1.elasticbeanstalk.com.</li></ul><p><strong>Save and Verify:</strong></p><ul><li>Save the CNAME record you just created.</li><li>Wait for the DNS propagation to complete, which may take some time (usually 24-48 hours).</li><li>Test your custom domain by entering it into your web browser. You should be redirected to your Tradeboard application on Elastic Beanstalk.</li></ul><figure><img src="https://i0.wp.com/www.marketcalls.in/wp-content/uploads/2024/06/image-17-1024x466.png?resize=1024%2C466&amp;ssl=1" alt="" height="466" width="1024"><figcaption></figcaption></figure><p><strong>Example:</strong></p><ul><li>Let’s say your custom domain is tradeboard.app.</li><li>You want to use the subdomain trade to access your Tradeboard application.</li><li>In your DNS settings, create a CNAME record with the following: <ul><li><strong>Name:</strong> trade</li><li><strong>Type:</strong> CNAME</li><li><strong>Value:</strong> tradeboard.ap-south-1.elasticbeanstalk.com (replace with your Elastic Beanstalk domain)</li></ul></li></ul><p>Once the DNS propagation completes, you’ll be able to access your Tradeboard application at trade.tradeboard.app.</p><p><strong>SSL Configuration in Cloudflare</strong></p><p>If you are using Cloudflare for DNS Management ensure to enable the flexible mode to access the tradeboard domain with https SSL certificate.</p><figure><img src="https://i0.wp.com/www.marketcalls.in/wp-content/uploads/2024/06/image-18-1024x524.png?resize=1024%2C524&amp;ssl=1" alt="" height="524" width="1024"><figcaption></figcaption></figure><p>By following these steps, you can successfully deploy Tradeboard in the cloud using Amazon AWS Elastic Beanstalk. You can then start configuring your trading strategies and begin your algorithmic trading journey.</p>',45)])])}const C=t(p,[["render",u]]);export{k as __pageData,C as default};
